        viewed: true,
        ...overrides,
    }
}

function deferredValue<T>() {
    let resolveValue: (value: T) => void = () => undefined
    const promise = new Promise<T>((resolve) => {
        resolveValue = resolve
    })

    return { promise, resolve: resolveValue }
}

function rejectableDeferred<T>() {
    let rejectValue: (error: unknown) => void = () => undefined
    const promise = new Promise<T>((_resolve, reject) => {
        rejectValue = reject
    })

    return { promise, reject: rejectValue }
}

function mockCodexAvailable() {
    vi.spyOn(agentCapabilitiesService, 'getSnapshot').mockReturnValue({availability: { error: null, loading: false, values: { codex: { available: true, error: null } } }})
}

function mockCustomCatalog() {
    const profile = mergeAgentProfiles([{command: ['custom'], defaultThinkingLevel: 'none', models: ['host-model'], name: 'custom'}]).find(({ name }) => name === 'custom');
    if (!profile) throw new Error('Missing custom test profile');
    const snapshot = { catalog: agentCatalogFixture(profile), error: null, loading: false };
    vi.mocked(agentCapabilitiesService.getCatalogSnapshot).mockImplementation(
        (key) => key === 'custom' ? snapshot : snapshotCatalogFixture(key),
    );
}

function setMobileBreakpoint(matches: boolean) {
    window.matchMedia = ((query: string) => ({
        addEventListener: vi.fn(),
        addListener: vi.fn(),
        dispatchEvent: vi.fn(),
        matches: matches && query.includes('max-width'),
        media: query,
        onchange: null,
        removeEventListener: vi.fn(),
        removeListener: vi.fn(),
    })) as unknown as typeof window.matchMedia
}

function worktreeStorage(): StorageService {
    return {
        onWorktreesChanged: vi.fn((callback) => {
            callback({ error: null, primaryStatus: null, project, records: [validWorktree] })
            return vi.fn()
        }),
    } as unknown as StorageService
}

function renderPopup(contextOverride: ActionContext = context, onClose = vi.fn(), stackPosition?: number) {
    function ActionPopupRenderProbe() {
        renderProbes.popup()

        return <ActionPopup anchorElement={document.body} context={contextOverride} onClose={onClose} stackPosition={stackPosition} />
    }

    render(
        <AppThemeProvider>
            <ActionPopupRenderProbe />
        </AppThemeProvider>,
    )

    return { onClose }
}

